/* ---------- deterministic fallbacks for ids the site doesn't know yet ---------- */

function hashId(id: string): number {
  let h = 0;
  for (let i = 0; i < id.length; i++) {
    h = (Math.imul(h, 31) + id.charCodeAt(i)) | 0;
  }
  return Math.abs(h);
}

/** Pinned color, or a deterministic pleasant HSL for unknown ids. */
export function colorFor(map: Record<string, string>, id: string): string {
  const pinned = map[id];
  if (pinned) return pinned;
  const hue = hashId(id) % 360;
  return `hsl(${hue} 65% 62%)`;
}

/** Pinned class suffix, or "unknown" (neutral gray setter in bench.css). */
export function classFor(map: Record<string, string>, id: string): string {
  return map[id] ?? "unknown";
}

/** Pinned monogram, or initials derived from the display name / id. */
export function monogramFor(id: string, display?: string): string {
  const pinned = MONOGRAM[id];
  if (pinned) return pinned;
  const source = (display ?? id).replace(/[^a-zA-Z0-9 ]/g, " ");
  const words = source.split(/\s+/).filter((w) => w.length > 0 && /[a-zA-Z]/.test(w[0] ?? ""));
  if (words.length === 0) return id.slice(0, 2).toUpperCase();
  return words
    .slice(0, 2)
    .map((w) => (w[0] ?? "").toUpperCase())
    .join("");
}

/* ---------- derived accessors ---------- */

/** True for the stack's headline row: no family/language/platform slice. */
export function isOverallScope(s: BenchStack): boolean {
  return !s.scope.family && !s.scope.language && !s.scope.platform;
}

/** Human label for a row's scope: "overall", "family: feature", "language: python", … */
export function scopeLabel(s: BenchStack): string {
  if (s.scope.family) return `family: ${s.scope.family}`;
  if (s.scope.language) return `language: ${s.scope.language}`;
  if (s.scope.platform) return `platform: ${s.scope.platform}`;
  return "overall";
}

/** Overall-scope stacks, best first — the leaderboard / matrix / scatter population. */
export const RANKED_STACKS: BenchStack[] = BENCH.stacks
  .filter(isOverallScope)
  .sort((a, b) => b.solution_rate - a.solution_rate);

/** Every published row (all scopes), grouped by scope label then rate — the report table. */
export const ALL_STACKS: BenchStack[] = [...BENCH.stacks].sort((a, b) => {
  const byScope = scopeLabel(a).localeCompare(scopeLabel(b));
  return byScope !== 0 ? byScope : b.solution_rate - a.solution_rate;
});

const stackByKey = new Map(RANKED_STACKS.map((s) => [`${s.harness}|${s.model}`, s]));

export function stackFor(harness: string, model: string): BenchStack | undefined {
  return stackByKey.get(`${harness}|${model}`);
}

/** Family ids present in the export, ranked by mean solution rate. */
export const FAMILIES: string[] = (() => {
  const seen = new Map<string, { sum: number; count: number }>();
  for (const s of BENCH.stacks) {
    const fam = s.scope.family;
    if (!fam || fam === "overall") continue;
    const agg = seen.get(fam) ?? { sum: 0, count: 0 };
    agg.sum += s.solution_rate;
    agg.count += 1;
    seen.set(fam, agg);
  }
  return [...seen.entries()]
    .sort((a, b) => b[1].sum / b[1].count - a[1].sum / a[1].count)
    .map(([fam]) => fam);
})();

/** Best harness cell for one (family, model) pair — the family table's atom. */
export function familyBest(family: string, model: string): BenchStack | undefined {
  let best: BenchStack | undefined;
  for (const s of BENCH.stacks) {
    if (s.scope.family !== family || s.model !== model) continue;
    if (!best || s.solution_rate > best.solution_rate) best = s;
  }
  return best;
}

export interface ModelStat {
  model: BenchModel;
  meanSolution: number;
  meanStrict: number;
  bestStack: BenchStack | undefined;
  medianCost: number | null;
  strongestFamily: { family: string; rate: number } | undefined;
  cells: number;
}

export function modelStat(modelId: string): ModelStat | undefined {
  const model = BENCH.models.find((m) => m.id === modelId);
  if (!model) return undefined;
  const cells = RANKED_STACKS.filter((s) => s.model === modelId);
  const meanSolution = cells.reduce((a, s) => a + s.solution_rate, 0) / (cells.length || 1);
  const meanStrict = cells.reduce((a, s) => a + s.strict_rate, 0) / (cells.length || 1);
  const bestStack = cells[0];
  const costs = cells
    .map((s) => s.cost_usd_median)
    .filter((c): c is number => c != null)
    .sort((a, b) => a - b);
  const medianCost = costs.length > 0 ? (costs[Math.floor(costs.length / 2)] ?? 0) : null;

  let strongestFamily: ModelStat["strongestFamily"];
  for (const fam of FAMILIES) {
    const best = familyBest(fam, modelId);
    if (best && (!strongestFamily || best.solution_rate > strongestFamily.rate)) {
      strongestFamily = { family: fam, rate: best.solution_rate };
    }
  }
  return {
    model,
    meanSolution,
    meanStrict,
    bestStack,
    medianCost,
    strongestFamily,
    cells: cells.length
  };
}

export function modelDisplay(id: string): string {
  return BENCH.models.find((m) => m.id === id)?.display ?? id;
}

